let quizPosition=0;
const quizQuestion=id=>QUIZ_BANK.find(q=>q.id===id);
const quizShuffle=list=>{const result=[...list];for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]]}return result};
function quizHTML(){const current=state.quiz;if(current&&!current.finished){quizPosition=Math.max(0,Math.min(quizPosition,current.ids.length-1));const q=quizQuestion(current.ids[quizPosition]);if(!q)return '<div class="empty">Não foi possível recuperar essa tentativa. Exporte seu progresso antes de iniciar uma nova.</div>';const answered=Object.keys(current.answers).length;return `<section class="quiz-panel"><div class="quiz-top"><div><span class="eyebrow">SIMULADO AUTORAL DE TREINO</span><h3>Questão ${quizPosition+1} de ${current.ids.length}</h3><p>${answered} respondida(s) • A tentativa fica salva neste navegador.</p></div><div><span class="muted">TEMPO RESTANTE</span><strong id="quiz-clock">${quizTime(current.endsAt-Date.now())}</strong></div></div><div class="track"><i style="width:${answered/current.ids.length*100}%"></i></div><p class="quiz-category">${esc(q.category)}</p><h3 class="quiz-prompt">${esc(q.prompt)}</h3><fieldset class="quiz-options"><legend class="sr-only">Escolha uma alternativa</legend>${current.order[q.id].map((option,pos)=>`<label class="quiz-option ${current.answers[q.id]===option?'chosen':''}"><input type="radio" name="quiz-answer" value="${option}" ${current.answers[q.id]===option?'checked':''}><span>${String.fromCharCode(65+pos)}</span><div>${esc(q.options[option])}</div></label>`).join('')}</fieldset><div class="quiz-navigation"><button data-quiz-position="${quizPosition-1}" ${quizPosition===0?'disabled':''}>← Anterior</button><button id="clear-answer">Limpar resposta</button><button data-quiz-position="${quizPosition+1}" ${quizPosition===current.ids.length-1?'disabled':''}>Próxima →</button></div><details class="topic-group"><summary>Navegar pelas questões</summary><div class="quiz-map">${current.ids.map((id,i)=>`<button data-quiz-position="${i}" class="${Number.isInteger(current.answers[id])?'answered':''} ${i===quizPosition?'current':''}" aria-label="Questão ${i+1}, ${Number.isInteger(current.answers[id])?'respondida':'sem resposta'}">${i+1}</button>`).join('')}</div></details><div class="quiz-footer"><p>O tempo continua contando se você sair da aba ou fechar o app. As respostas são salvas ao selecionar.</p><button id="finish-quiz" class="study">Finalizar e corrigir</button></div></section>`}
const history=state.quizHistory||[],latest=history[0];return `<div class="quiz-panel"><span class="eyebrow">PRATIQUE PARA A PROVA</span><h2>Simulado · ${esc(getCareer().org)}</h2><p>Banco desta trilha: ${QUIZ_BANK.length} questões autorais, com quatro alternativas, gabarito comentado e resultado por disciplina. Há questões em ${new Set(QUIZ_BANK.map(q=>q.category)).size} disciplinas; a cobertura do banco é menor que a do programa de estudos. Este simulado não é uma prova oficial nem reproduz a distribuição de um futuro edital.</p><div class="form-grid"><label>Quantidade de questões<select id="quiz-size">${quizSizeOptions(QUIZ_BANK.length)}</select></label><label>Disciplina<select id="quiz-discipline"><option value="">Todas as disciplinas</option>${[...new Set(QUIZ_BANK.map(q=>q.category))].map(c=>`<option>${esc(c)}</option>`).join('')}</select></label></div><p>As perguntas e a ordem das alternativas são embaralhadas. Treinos por disciplina usam até a quantidade disponível no banco. Novas tentativas reutilizam as questões deste banco.</p><button class="study" id="start-quiz">▶ Iniciar simulado</button></div>${latest?quizResultHTML(latest):''}${history.length?`<section class="quiz-panel"><h3>Histórico de tentativas</h3><div class="table-scroll"><table><thead><tr><th>Conclusão</th><th>Questões</th><th>Acertos</th><th>Aproveitamento</th></tr></thead><tbody>${history.map(h=>`<tr><td>${new Date(h.finishedAt).toLocaleString('pt-BR')}</td><td>${h.total}</td><td>${h.correct}</td><td>${Math.round(h.correct/h.total*100)}%</td></tr>`).join('')}</tbody></table></div><p>Os resultados dos simulados concluídos já entram nos totais do painel. Não é necessário adicioná-los novamente no registro manual de questões.</p></section>`:''}`}
function quizTime(ms){const seconds=Math.max(0,Math.ceil(ms/1000));return String(Math.floor(seconds/3600)).padStart(2,'0')+':'+String(Math.floor(seconds%3600/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')}
function startQuiz(){const requested=Number($('#quiz-size').value),category=$('#quiz-discipline').value,pool=QUIZ_BANK.filter(q=>!category||q.category===category),ids=quizShuffle(pool).slice(0,requested).map(q=>q.id),minutes=ids.length*3,order={};for(const id of ids)order[id]=quizShuffle([0,1,2,3]);state.quiz={careerId:currentCareerId,ids,order,answers:{},startedAt:Date.now(),endsAt:Date.now()+minutes*60000};quizPosition=0;save();render()}
function finishQuiz(expired=false){const attempt=state.quiz;if(!attempt)return;if(!expired){const blank=attempt.ids.filter(id=>!Number.isInteger(attempt.answers[id])).length;if(blank&&!confirm(`Faltam ${blank} questão(ões) sem resposta. Finalizar mesmo assim?`))return}const correct=attempt.ids.filter(id=>attempt.answers[id]===quizQuestion(id)?.answer).length;state.quizHistory=[{...attempt,finishedAt:Date.now(),expired,total:attempt.ids.length,correct},...(state.quizHistory||[])].slice(0,20);state.quiz=null;save();render();toast(expired?'Tempo encerrado. Seu simulado foi corrigido.':'Simulado corrigido e resultado salvo.')}
function quizResultHTML(result){const groups={};for(const id of result.ids){const q=quizQuestion(id);if(!q)continue;if(!groups[q.category])groups[q.category]={total:0,correct:0};groups[q.category].total++;if(result.answers[id]===q.answer)groups[q.category].correct++}return `<section class="quiz-panel"><span class="eyebrow">ÚLTIMO RESULTADO${result.expired?' · TEMPO ENCERRADO':''}</span><div class="quiz-top"><div><h2>${result.correct} de ${result.total} acertos</h2><p>${Math.round(result.correct/result.total*100)}% de aproveitamento. Questões sem resposta contam como não acertadas.</p></div><div class="quiz-score">${Math.round(result.correct/result.total*100)}%</div></div><h3>Desempenho por disciplina</h3><div class="table-scroll"><table><thead><tr><th>Disciplina</th><th>Acertos</th><th>%</th></tr></thead><tbody>${Object.entries(groups).map(([cat,r])=>`<tr><td>${esc(cat)}</td><td>${r.correct}/${r.total}</td><td>${Math.round(r.correct/r.total*100)}%</td></tr>`).join('')}</tbody></table></div><h3>Gabarito comentado</h3>${result.ids.map((id,i)=>{const q=quizQuestion(id);if(!q)return '';const answer=result.answers[id],correct=answer===q.answer,options=result.order[id]||[0,1,2,3];return `<details class="topic-group quiz-correction ${correct?'correct':'incorrect'}"><summary>${i+1}. ${correct?'✓ Acertou':Number.isInteger(answer)?'✕ Errou':'— Sem resposta'} · ${esc(q.category)}</summary><p><b>${esc(q.prompt)}</b></p><p>Sua resposta: ${Number.isInteger(answer)?esc(q.options[answer]):'Não respondida'}</p><p><b>Gabarito: ${String.fromCharCode(65+options.indexOf(q.answer))} — ${esc(q.options[q.answer])}</b></p><p>${esc(q.explanation)}</p>${q.source?`<p><a target="_blank" rel="noopener" href="${esc(q.source)}">Conferir a fonte oficial ↗</a></p>`:''}<button data-open="${q.topic}">Revisar assunto e videoaulas →</button></details>`}).join('')}</section>`}
function quizSizeOptions(limit){return [...new Set([15,30,60].map(n=>Math.min(n,limit)))].map((n,i,rows)=>`<option value="${n}" ${i===rows.length-1?'selected':''}>${n} questões · até ${n*3} minutos</option>`).join('')}
function bindQuiz(){if($('#quiz-discipline'))$('#quiz-discipline').onchange=e=>{const count=QUIZ_BANK.filter(q=>!e.target.value||q.category===e.target.value).length;$('#quiz-size').innerHTML=quizSizeOptions(count)};if($('#start-quiz'))$('#start-quiz').onclick=startQuiz;if($('#finish-quiz'))$('#finish-quiz').onclick=()=>finishQuiz();if($('#clear-answer'))$('#clear-answer').onclick=()=>{delete state.quiz.answers[state.quiz.ids[quizPosition]];save();render()};document.querySelectorAll('input[name="quiz-answer"]').forEach(input=>input.onchange=e=>{state.quiz.answers[state.quiz.ids[quizPosition]]=Number(e.target.value);save();render()});document.querySelectorAll('[data-quiz-position]').forEach(button=>button.onclick=()=>{quizPosition=Number(button.dataset.quizPosition);render()})}
function quizTick(){if(!state.quiz)return;if(state.quiz.endsAt<=Date.now()){finishQuiz(true);return}if($('#quiz-clock'))$('#quiz-clock').textContent=quizTime(state.quiz.endsAt-Date.now())}
